// src/services/http-client.ts
function buildCommonHeaders(config, options) {
  const headers = {
    Authorization: `Bearer ${config.authToken}`,
    Accept: "application/json"
  };
  if (options?.includeContentType !== false) {
    headers["Content-Type"] = "application/json";
  }
  if (config.organizationUnitId) {
    headers["X-UIPATH-OrganizationUnitId"] = config.organizationUnitId.toString();
  }
  if (config.folderKey) {
    headers["x-uipath-folderkey"] = config.folderKey;
  }
  return headers;
}
function buildOrchestratorHeaders(config) {
  return buildCommonHeaders(config);
}
function buildOrchestratorUrl(config, path) {
  return `${config.baseUrl}/${config.organizationId}/${config.tenantName}/orchestrator_${path}`;
}
async function orchestratorGet(config, path) {
  const url = buildOrchestratorUrl(config, path);
  const headers = buildOrchestratorHeaders(config);
  logger.debug(`GET: ${url}`);
  const response = await fetch(url, {
    method: "GET",
    headers
  });
  if (!response.ok) {
    const errorText = await response.text();
    logger.error(`GET ${url} failed: ${response.status}`);
    logger.error(`Response: ${errorText.substring(0, 500)}`);
    if (response.status === 404) {
      throw new Error(`API request failed: 404 ${response.statusText}. Resource not found. Verify the process key, feed ID, folder, tenant, and permissions, then retry. - ${errorText}`);
    }
    throw new Error(`API request failed: ${response.status} ${response.statusText} - ${errorText}`);
  }
  const getText = await response.text();
  const [getParseErr, getParsed] = catchError(() => JSON.parse(getText));
  if (getParseErr)
    throw new Error(`Failed to parse API response body: ${getParseErr.message}`);
  return getParsed;
}

