async function validateMaestroInputs(config, inputs) {
  const [entryErr, entryPoints] = await catchError(getMaestroEntryPoints(config));
  if (entryErr) {
    return {
      valid: false,
      errors: [`Failed to validate inputs: ${entryErr.message}`]
    };
  }
  if (entryPoints.length === 0) {
    return {
      valid: false,
      errors: ["No entry points found for this process"]
    };
  }
  const entryPoint = entryPoints[0];
  const [parseErr, inputSchema] = catchError(() => JSON.parse(entryPoint.InputArguments));
  if (parseErr) {
    return {
      valid: false,
      errors: [`Failed to validate inputs: ${parseErr.message}`]
    };
  }
  if (inputSchema.type !== "object") {
    return { valid: true };
  }
  const errors = [];
  const requiredProps = Array.isArray(inputSchema.required) ? inputSchema.required.filter((prop) => {
    return typeof prop === "string";
  }) : [];
  for (const prop of requiredProps) {
    if (!(prop in inputs)) {
      errors.push(`Missing required property: ${prop}`);
    }
  }
  if (isRecord(inputSchema.properties)) {
    const properties = inputSchema.properties;
    const rejectUnknownProperties = inputSchema.additionalProperties === false;
    for (const [key, value] of Object.entries(inputs)) {
      if (!(key in properties)) {
        if (rejectUnknownProperties) {
          errors.push(`Unknown input property: ${key}`);
        }
        continue;
      }
      const propertySchema = properties[key];
      if (!isRecord(propertySchema) || propertySchema.type === undefined) {
        continue;
      }
      const typeErrors = validateInputType(key, value, propertySchema.type);
      errors.push(...typeErrors);
    }
  }
  return {
    valid: errors.length === 0,
    errors: errors.length > 0 ? errors : undefined
  };
}
function validateInputType(key, value, expectedType) {
  const expectedTypes = Array.isArray(expectedType) ? expectedType.filter((type) => typeof type === "string") : typeof expectedType === "string" ? [expectedType] : [];
  if (expectedTypes.length === 0) {
    return [];
  }
  const matches = expectedTypes.some((type) => matchesJsonSchemaType(value, type));
  if (matches) {
    return [];
  }
  return [
    `Property '${key}' should be ${expectedTypes.join(" or ")}, got ${getJsonValueType(value)}`
  ];
}
function matchesJsonSchemaType(value, expectedType) {
  switch (expectedType) {
    case "string":
      return typeof value === "string";
    case "number":
      return typeof value === "number" && Number.isFinite(value);
    case "integer":
      return typeof value === "number" && Number.isInteger(value);
    case "boolean":
      return typeof value === "boolean";
    case "object":
      return isRecord(value);
    case "array":
      return Array.isArray(value);
    case "null":
      return value === null;
    default:
      return true;
  }
}
function getJsonValueType(value) {
  if (value === null) {
    return "null";
  }
  if (Array.isArray(value)) {
    return "array";
  }
  return typeof value;
}
async function validateMaestroInputsOrThrow(config, inputs) {
  const validation = await validateMaestroInputs(config, inputs);
  if (!validation.valid) {
    const errorList = validation.errors?.join(`
`) ?? "Invalid inputs";
    throw new Error(`Input validation failed:
${errorList}`);
  }
}
function assertInputRecord(value) {
  if (!isRecord(value)) {
    throw new Error(`Maestro inputs must be a JSON object, got ${getJsonValueType(value)}.`);
  }
  return value;
}
async function parseMaestroInputs(inputSource) {
  const parsed = await parseJsonInputOrFile(inputSource);
  return assertInputRecord(parsed);
}

// src/utils/validation.ts
function parseFolderId(raw, fallback) {
  if (!raw)
    return fallback;
  const parsed = parseInt(raw, 10);
  if (Number.isNaN(parsed)) {
    throw new Error(`Invalid folder-id: "${raw}". Must be a number.`);
  }
  if (parsed < 0) {
    throw new Error(`Invalid folder-id: "${raw}". Must be non-negative.`);
  }
  return parsed;
}

