async function safeMkdir(fs, dir) {
  const [err] = await catchError(fs.mkdir(dir));
  if (err) {
    const code = err.code;
    if (code !== "EEXIST") {
      throw err;
    }
  }
}
function assertValidIdentifier(value, kind, label) {
  if (!VALID_PROJECT_NAME_REGEX.test(value)) {
    throw new Error(`Invalid ${kind} "${value}". ${label} can only contain letters, numbers, underscores (_), and hyphens (-).`);
  }
}
async function assertProjectDirUsable(fs, projectDir, name, force) {
  const [statErr] = await catchError(fs.stat(projectDir));
  if (statErr) {
    const code = statErr.code;
    if (code !== "ENOENT" && code !== "PathNotFound") {
      throw statErr;
    }
    return;
  }
  if (force) {
    return;
  }
  const existingEntries = await fs.readdir(projectDir);
  if (existingEntries.length > 0) {
    throw new Error(`Directory "${name}" already exists and is not empty. Use --force to overwrite.`);
  }
}
async function initMaestroProject(name, options) {
  assertValidIdentifier(name, "project name", "Name");
  const processId = options.processId ?? "Process_1";
  assertValidIdentifier(processId, "process id", "Process id");
  const fs = getFileSystem();
  const { prepareProjectLocation } = await import("./index-hfsfzg4k.js");
  const { projectDir, autoCreatedSolution } = await prepareProjectLocation(fs, fs.path.resolve(name), name, { skipRegistration: options.skipSolutionRegistration === true });
  await assertProjectDirUsable(fs, projectDir, name, options.force === true);
  await safeMkdir(fs, projectDir);
  const projectId = crypto.randomUUID();
  const startEventId = "Event_start";
  const entryPointUniqueId = crypto.randomUUID();
  const { buildBpmnPackageMetadata, formatBpmnPackageFile } = await import("./index-938ee96p.js");
  const packageMetadata = buildBpmnPackageMetadata({
    bpmnFile: `${name}.bpmn`,
    entryPoints: [
      {
        startEventId,
        entryPointId: entryPointUniqueId,
        displayName: "Manual trigger",
        input: { type: "object", properties: {} },
        output: { type: "object", properties: {} }
      }
    ],
    projectId,
    resources: []
  });
  const bpmn = `<?xml version="1.0" encoding="UTF-8"?>
<bpmn:definitions xmlns:bpmn="http://www.omg.org/spec/BPMN/20100524/MODEL" xmlns:uipath="http://uipath.org/schema/bpmn" xmlns:bpmndi="http://www.omg.org/spec/BPMN/20100524/DI" xmlns:dc="http://www.omg.org/spec/DD/20100524/DC" xmlns:di="http://www.omg.org/spec/DD/20100524/DI" exporter="UiPath Maestro (https://uipath.com)" exporterVersion="${package_default.version}">
  <bpmn:process id="${processId}" name="Maestro Process">
    <bpmn:extensionElements>
      <uipath:variables version="v1" />
      <uipath:bindings version="v1" />
    </bpmn:extensionElements>
    <bpmn:startEvent id="${startEventId}" name="core.trigger.manual">
      <bpmn:extensionElements>
        <uipath:entryPointId value="${entryPointUniqueId}" />
      </bpmn:extensionElements>
      <bpmn:outgoing>_Implicit_EndEvent_Flow</bpmn:outgoing>
    </bpmn:startEvent>
    <bpmn:endEvent id="_Implicit_EndEvent">
      <bpmn:incoming>_Implicit_EndEvent_Flow</bpmn:incoming>
    </bpmn:endEvent>
    <bpmn:sequenceFlow id="_Implicit_EndEvent_Flow" sourceRef="${startEventId}" targetRef="_Implicit_EndEvent" />
  </bpmn:process>
  <bpmndi:BPMNDiagram id="Diagram_1">
    <bpmndi:BPMNPlane id="Plane_1" bpmnElement="${processId}">
      <bpmndi:BPMNShape id="S_${startEventId}" bpmnElement="${startEventId}">
        <dc:Bounds x="256" y="144" width="96" height="96" />
        <bpmndi:BPMNLabel>
          <dc:Bounds x="256" y="245" width="96" height="14" />
        </bpmndi:BPMNLabel>
      </bpmndi:BPMNShape>
      <bpmndi:BPMNShape id="S__Implicit_EndEvent" bpmnElement="_Implicit_EndEvent">
        <dc:Bounds x="512" y="144" width="96" height="96" />
      </bpmndi:BPMNShape>
      <bpmndi:BPMNEdge id="E__Implicit_EndEvent_Flow" bpmnElement="_Implicit_EndEvent_Flow">
        <di:waypoint x="352" y="192" />
        <di:waypoint x="512" y="192" />
      </bpmndi:BPMNEdge>
    </bpmndi:BPMNPlane>
  </bpmndi:BPMNDiagram>
</bpmn:definitions>
`;
  const { default: BpmnModdle } = await import("./index-xes9hekf.js");
  const moddle = new BpmnModdle;
  const { warnings } = await moddle.fromXML(bpmn);
  const criticalWarnings = warnings.filter((w) => !w.message.includes("<uipath:"));
  if (criticalWarnings.length > 0) {
    const msgs = criticalWarnings.map((w) => w.message).join("; ");
    throw new Error(`BPMN validation failed: ${msgs}`);
  }
  const projectUiproj = {
    Name: name,
    ProjectType: "ProcessOrchestration"
  };
  await fs.writeFile(fs.path.join(projectDir, "project.uiproj"), `${JSON.stringify(projectUiproj, null, 2)}
`);
  await fs.writeFile(fs.path.join(projectDir, "operate.json"), formatBpmnPackageFile(packageMetadata["operate.json"]));
  await fs.writeFile(fs.path.join(projectDir, "entry-points.json"), formatBpmnPackageFile(packageMetadata["entry-points.json"]));
  await fs.writeFile(fs.path.join(projectDir, "bindings_v2.json"), formatBpmnPackageFile(packageMetadata["bindings_v2.json"]));
  await fs.writeFile(fs.path.join(projectDir, "package-descriptor.json"), formatBpmnPackageFile(packageMetadata["package-descriptor.json"]));
  await fs.writeFile(fs.path.join(projectDir, `${name}.bpmn`), bpmn);
  const { tryRegisterProjectInParentSolution } = await import("./index-hfsfzg4k.js");
  const solutionRegistration = await tryRegisterProjectInParentSolution(fs, projectDir, { skipRegistration: options.skipSolutionRegistration === true });
  let projectArtifacts;
  if ((solutionRegistration.Status === "Registered" || solutionRegistration.Status === "AlreadyRegistered") && solutionRegistration.Solution && solutionRegistration.ProjectId) {
    projectArtifacts = await ensureProjectArtifacts({
      solutionDir: fs.path.dirname(solutionRegistration.Solution),
      projectId: solutionRegistration.ProjectId,
      projectName: name,
      projectType: "ProcessOrchestration"
    });
  }
  const data = {
    Status: "Created successfully",
    Path: projectDir,
    SolutionRegistration: solutionRegistration
  };
  if (autoCreatedSolution) {
    data.AutoCreatedSolution = autoCreatedSolution;
  }
  if (projectArtifacts) {
    data.ProjectArtifacts = projectArtifacts;
  }
  if (solutionRegistration.Instructions) {
    data.NextSteps = solutionRegistration.Instructions;
  }
  OutputFormatter.success({
    Result: RESULTS.Success,
    Code: "MaestroInit",
    Data: data
  });
}

